let fastFile = {path: "/", isFile: false, name: "...", isDirectory: true};
let files = [fastFile, {path: "", isFile: false, name: "/"}];
let medias = [];
let rootPath = "/";
let webName = "";
let apps = [];
let tabPage = 1;
let defaultPage = 'apps';

// 主题切换功能
function applyTheme(theme) {
    var resolvedTheme = theme;
    if (theme === "follow_system") {
        resolvedTheme = window.matchMedia("(prefers-color-scheme: dark)").matches ? "dark" : "light";
    }
    document.body.className = "theme-" + resolvedTheme;
    localStorage.setItem("theme", theme);
}

function getThemeName(theme) {
    switch (theme) {
        case "light": return "浅色";
        case "dark": return "暗色";
        case "emerald": return "翠绿";
        case "follow_system": return "跟随系统";
        default: return theme;
    }
}

// 监听系统主题变化（用于跟随系统模式）
window.matchMedia("(prefers-color-scheme: dark)").addEventListener("change", function(e) {
    if (localStorage.getItem("theme") === "follow_system") {
        applyTheme("follow_system");
    }
});

initConfig();

function truncateString(b, a) {
    if (b.length > a) {
        return b.slice(0, a - 3) + "..."
    }
    return b
}

function showUploadDialog() {
    $("#select-file").val("");
    $("#displayFile").val("");
    $("#uploadFileDialog").modal("show")
}

function uploadFile(b, c, a) {
    let ajax = new XMLHttpRequest();
    ajax.open("POST", "/uploadFile", true);
    ajax.setRequestHeader("token", localStorage.getItem("token"));
    ajax.upload.addEventListener("progress", function (d) {
    }, false);
    ajax.send(b);
    ajax.onreadystatechange = function () {
        if (ajax.readyState === 4) {
            if (ajax.status >= 200 && ajax.status < 300 || ajax.status === 304) {
                c(ajax.responseText)
            } else {
                if (ajax.status >= 302) {
                    window.location.href = ajax.getResponseHeader("Location")
                } else {
                    if (ajax.status === 500) {
                        a(ajax.responseText)
                    } else {
                        a("上传文件失败")
                    }
                }
            }
        }
    }
}

function showContextMenu(a, c) {
    var b = $(".context-menu");
    b.css({display: "block", left: a + "px", top: c + "px"});
    b.on("click", function () {
        hideContextMenu()
    })
}

function hideContextMenu() {
    var a = $(".context-menu");
    a.css("display", "none")
}

$(function () {
    let selector = $("#select-file");
    $("#displayFile").on("change", function (d) {
        $("#select-file").val($("#displayFile").val());
        const c = d.target;
        const b = c.files[0];
        if (b) {
            uploadData = new FormData();
            uploadData.append("file", b);
            var a = $(".select_send_device");
            a.empty();
            a.append("<tr onclick='startSendFile(null)' class=\"select_send_device_item\"><td>本机设备</td><td></td></tr>\n");
            for (let i = 0; i < onLineDeviceList.length; i++) {
                a.append("<tr onclick='startSendFile(\"" + onLineDeviceList[i].address + '")\' class="select_send_device_item"><td>' + onLineDeviceList[i].devName + "</td><td>" + onLineDeviceList[i].devIP + "</td></tr>\n")
            }
            $("#uploadFileDialog").modal("hide");
            $("#devSelectDialog").modal("show")
        }
    });
    $(document).on("dragover", function (a) {
        selector.css("display", "block");
        a.preventDefault()
    });
    selector.on("dragenter", function () {
        selector.attr("placeholder", "松手即可上传")
    });
    selector.on("dragleave", function () {
        selector.attr("placeholder", "拖拽到此处上传文件")
    });
    selector.on("drop", function (b) {
        selector.attr("placeholder", "点击选择文件或者拖拽文件到此处");
        $("#uploadFileDialog").modal("hide");
        uploadData = new FormData();
        Array.from(b.originalEvent.dataTransfer.files).forEach(function (c) {
            uploadData.append("file", c)
        });
        var a = $(".select_send_device");
        a.empty();
        a.append("<tr onclick='startSendFile(null)' class=\"select_send_device_item\"><td>本机设备</td><td></td></tr>\n");
        for (let i = 0; i < onLineDeviceList.length; i++) {
            a.append("<tr onclick='startSendFile(\"" + onLineDeviceList[i].address + '")\' class="select_send_device_item"><td>' + onLineDeviceList[i].devName + "</td><td>" + onLineDeviceList[i].devIP + "</td></tr>\n")
        }
        $("#uploadFileDialog").modal("hide");
        $("#devSelectDialog").modal("show");
        b.preventDefault()
    });
    $(document).on("contextmenu", function (a) {
        a.preventDefault();
        if ($(a.target).hasClass("media-file")) {
            let fileName = $(a.target).attr("file-name");
            let path = $(a.target).attr("path");
            let contextMenu = $(".context-menu");
            let requestUrl = window.location.origin + "/file/" + fileName + "?path=" + encodeURIComponent(path) + "&token=" + localStorage.getItem("token");
            contextMenu.empty();
            contextMenu.append('<a class="menu-item" onclick="openFile(\'' + fileName + "','" + path + "')\">打开</a>");
            contextMenu.append('<a class="menu-item" onclick="copyToClip(\'' + requestUrl + "')\">复制链接</a>");
            showContextMenu(a.clientX, a.clientY)
        } else {
            if ($(a.target).hasClass("media-dir")) {
                let index = $(a.target).attr("m-index");
                let contextMenu = $(".context-menu");
                contextMenu.empty();
                contextMenu.append('<a class="menu-item" onclick="openHash(' + index + ')">打开</a>');
                showContextMenu(a.clientX, a.clientY)
            }
        }
    });
    $(document).on("click", function () {
        hideContextMenu()
    });
    // 侧边栏导航改用 navTo()，onclick 已内联在 HTML 中
    $(".media-img-select").click(function (a) {
        a = window.event || a;
        if (a.stopPropagation) a.stopPropagation(); else a.cancelBubble = true;
    });
    $(".file-icon-select").click(function (a) {
        a = window.event || a;
        if (a.stopPropagation) a.stopPropagation(); else a.cancelBubble = true;
    });
    $('.web-name').on('blur', function () {
        webName = $(this).val();
        updateWebName();
    });
    // 保留 hash 监听以支持浏览器前进后退
    window.onhashchange = locationHashChanged;
});

function updateWebName() {
    post({
        url: "/updateWebName", data: JSON.stringify({webName: webName}), success: function (a) {
        }, error: function (a) {
            console.error(a.message)
        }
    })
}

function checkPass() {
    const a = setInterval(function () {
        post({
            url: "/checkPass", data: {}, success: function (b) {
                if (b.pass) {
                    clearInterval(a);
                    location.reload()
                }
            }, error: function (b) {
                console.error(b.message)
            }
        })
    }, 2000)
}

function initConfig() {
    post({
        url: "/initConfig", data: JSON.stringify({test: 1}), success: function (a) {
            rootPath = a.rootPath;
            webName = a.name;
            localStorage.setItem("token", a.token);
            // 应用服务器推送的主题
            if (a.theme) {
                applyTheme(a.theme);
            } else {
                // 使用本地缓存的主题
                var savedTheme = localStorage.getItem("theme");
                if (savedTheme) {
                    applyTheme(savedTheme);
                } else {
                    applyTheme("light");
                }
            }
            if (a.pass) {
                if (a.menus && a.menus.length > 0) {
                    defaultPage = a.menus[0].key;
                    buildSidebar(a.menus);
                }
                $(".lyear-layout-web").show();
                initWS();
                initView()
            } else {
                $("#myModal").modal("show");
                checkPass()
            }
        }, error: function (a) {
            console.error(a.message)
        }
    })
}

// 导航切换 - 直接调用 locationHashChanged() 而非依赖 hashchange 事件
function navTo(page) {
    switch (page) {
        case 'apps':
            window.location.hash = 'nav-item-apps';
            break;
        case 'media':
            window.location.hash = 'nav-item-media?index=-1';
            break;
        case 'files':
            window.location.hash = 'nav-item-files' + rootPath + '?isBack=false';
            break;
        case 'chat':
            window.location.hash = 'nav-item-chat';
            break;
        case 'draw':
            window.location.hash = 'nav-item-draw';
            break;
    }
    // 直接调用，不依赖 onhashchange（hash 相同时不会触发）
    locationHashChanged();
}

function initView() {
    $('.web-name').val(webName);
    navTo(defaultPage);
}

function openFile(a, b) {
    let requestUrl = "/file/" + a + "?path=" + encodeURIComponent(b) + "&token=" + localStorage.getItem("token");
    window.open(requestUrl, "_blank")
}

function copyToClip(b) {
    var a = document.createElement("input");
    a.setAttribute("value", b);
    document.body.appendChild(a);
    a.select();
    document.execCommand("copy");
    document.body.removeChild(a);
    lightyear.notify("复制成功", "success", 1000)
}

function openApkFile(b, a) {
    let requestUrl = "/apkfile/" + b + "?packageName=" + a + "&token=" + localStorage.getItem("token");
    window.open(requestUrl, "_blank")
}

function openMedia(a) {
    if (filesSelectCount > 0) {
        let select = $(a).children(".media-img-select");
        select.prop("checked", !select.is(":checked"));
        mediaSelect(select)
    } else {
        openFile($(a).attr("file-name"), $(a).attr("path"))
    }
}

function openMediaFolder(a, b) {
    if (filesSelectCount > 0) {
        let select = $(a).children(".media-img-select");
        select.prop("checked", !select.is(":checked"));
        mediaSelect(select)
    } else {
        openHash(b)
    }
}

function openHash(a) {
    window.location.hash = "nav-item-media?index=" + a
}

function handleMediaIntersection(a, b) {
    a.forEach(function (c) {
        if (c.isIntersecting) {
            const d = $(c.target).find(".media-img");
            d.css("background-image", "url('" + d.data("url") + "')");
            b.unobserve(c.target)
        }
    })
}

function handleApplistIntersection(a, b) {
    a.forEach(function (c) {
        if (c.isIntersecting) {
            const d = $(c.target).find(".app-img");
            d.css("background-image", "url('" + d.data("url") + "')");
            b.unobserve(c.target)
        }
    })
}

const options = {root: null, rootMargin: "0px", threshold: 0.5};
const mediaObserver = new IntersectionObserver(handleMediaIntersection, options);
const appListObserver = new IntersectionObserver(handleApplistIntersection, options);

function mediaList(a) {
    $(".media-content").empty();
    post({
        url: "/media", type: "post", data: JSON.stringify({folderIndex: a}), success: function (b) {
            medias = b;
            b.forEach(function (d, c) {
                let cardBox;
                if (d.isDirectory) {
                    cardBox = $("<div is-directory='true' m-index='" + d.index + '\' class="media-dir cardBox media-item" onclick="openMediaFolder(this,' + d.index + ')"></div>')
                } else {
                    cardBox = $("<div is-directory='false' m-index='" + d.index + "' i-index='" + d.subIndex + "' file-name='" + d.name + "' path='" + d.path + '\'  class="media-file cardBox media-item" onclick="openMedia(this)"></div>')
                }
                cardBox.append($('<div class="media-img" data-url=\'/imageload/' + d.name + "?index=" + d.imgIndex + "&token=" + localStorage.getItem("token") + "'></div>"));
                cardBox.append('<input name="checkbox" value="0" type="checkbox" onclick=\'event.cancelBubble=true;mediaSelect(this)\'  class="media-img-select">');
                if (d.isVideo) {
                    cardBox.append($('<div class="media-video-time">' + d.videoTime + "</div>"))
                }
                if (d.isDirectory) {
                    cardBox.append("<div>" + truncateString(d.name, 18) + "</div>")
                }
                $(".media-content").append(cardBox);
                mediaObserver.observe(cardBox[0])
            })
        }, error: function (b) {
            console.error(b.message)
        }
    })
}

var filesSelectCount = 0;

function mediaSelect(a) {
    if ($(a).is(":checked")) {
        filesSelectCount++
    } else {
        filesSelectCount--
    }
    if (filesSelectCount > 0) {
        $(".download-files").show()
    } else {
        $(".download-files").hide()
    }
    $(".download-files").text("下载文件(" + filesSelectCount + ")")
}

function fileSelect(a) {
    if ($(a).is(":checked")) {
        filesSelectCount++
    } else {
        filesSelectCount--
    }
    if (filesSelectCount > 0) {
        $(".download-files").show()
    } else {
        $(".download-files").hide()
    }
    $(".download-files").text("下载文件(" + filesSelectCount + ")")
}

function resetMediaSelect() {
    filesSelectCount = 0;
    $(".download-files").hide()
}

function appList() {
    $(".app-content").empty();
    post({
        url: "/apps", data: JSON.stringify({}), success: function (a) {
            apps = a.list;
            apps.forEach(function (c, b) {
                let appbox = $("<div class='appBox media-item' onclick='openApkFile(\"" + c.name + '","' + c.packageName + "\")'></div>");
                appbox.append($("<div class='app-img' data-url='/appicon?packageName=" + c.packageName + "'/>"));
                appbox.append($("<div>" + c.name + "</div>"));
                appbox.append($("<div>" + c.length + "</div>"));
                appbox.append($("<img class='app-select' src='/drawable?name=ic_image_un_select'/>"));
                $(".app-content").append(appbox);
                appListObserver.observe(appbox[0])
            })
        }, error: function (a) {
        }
    })
}

function dirClick(a, b) {
    window.location.hash = "nav-item-files" + b + "?isBack=" + a
}

function openDir(a, b) {
    post({
        url: "/files", data: JSON.stringify({path: b, isBack: a}), success: function (c) {
            viewEmpty();
            fastFile.path = c.path;
            $(".path-text").text(c.path);
            files = c.list;
            let i = 0;
            files.forEach(function (e, d) {
                let li;
                // 第一个 item (d===0) 固定为返回上一级，强制使用 dirClick
                if (d === 0 || e.isDirectory) {
                    li = $("<div file-path='" + e.path + "' class='file-item' onclick=\"dirClick('" + (d === 0) + "',encodeURI($(this).attr('file-path')))\"></div>")
                } else {
                    li = $("<div file-path='" + e.path + "'  class='file-item' onclick=\"openFile('" + e.name + "',$(this).attr('file-path'))\"></div>")
                }
                if (d !== 0) {
                    li.append('<input name="checkbox" value="0" type="checkbox" onclick="event.cancelBubble=true;fileSelect(this)" class="file-img-select">')
                }
                // 第一个 item 固定显示文件夹图标（返回上一级）
                if (d === 0 || e.isDirectory) {
                    li.append("<div class='file-item-icon file-item-base file-icon-folder'></div>")
                } else {
                    li.append("<div class='file-item-icon file-item-base file-icon-file'></div>")
                }
                let info = $('<div class="file-item-info"></div>');
                info.append($("<div class='file-item-name'>" + e.name + "</div>"));
                if (d === 0) {
                    info.append($("<div class='file-item-time file-item-base'></div>"))
                } else {
                    info.append($("<div class='file-item-time file-item-base'>" + e.time + "</>"))
                }
                li.append(info);
                $(".filelist").append(li);
                i++
            })
        }, error: function (c) {
            console.log(c.message)
        }
    })
}

function viewEmpty() {
    resetMediaSelect();
    $(".filelist").empty();
    $(".media-content").empty();
    $(".app-content").empty();
    document.body.scrollTop = document.documentElement.scrollTop = 0
}

function downloadMedia() {
    list = [];
    $(".media-item").each(function (a, b) {
        if ($(b).find(".media-img-select").is(":checked")) {
            isDirectory = $(b).attr("is-directory");
            a = -1;
            subIndex = -1;
            if (isDirectory === "true") {
                a = $(b).attr("m-index")
            } else {
                a = $(b).attr("m-index");
                subIndex = $(b).attr("i-index")
            }
            list.push({index: a - 0, subIndex: subIndex - 0, isDirectory: isDirectory === "true"})
        }
    });
    lightyear.notify("文件正在打包中...", "info", 1000);
    lightyear.loading("show");
    post({
        url: "/compressMedias", data: JSON.stringify({list: list}), success: function (a) {
            lightyear.loading("hide");
            lightyear.notify("文件打包成功，开始下载", "success", 1000);
            window.location.href = "/downloadZipFile?tempFile=" + a.tempFile
        }, error: function (a) {
            console.error(a.message);
            lightyear.loading("hide");
            lightyear.notify("打包文件失败", "danger", 1000)
        }
    })
}

function downloadFile() {
    list = [];
    $(".file-item").each(function (a, b) {
        if ($(b).find(".file-img-select").is(":checked")) {
            filePath = $(b).attr("file-path");
            list.push(filePath)
        }
    });
    lightyear.notify("文件正在打包中...", "info", 1000);
    lightyear.loading("show");
    post({
        url: "/compressFiles", data: JSON.stringify({list: list}), success: function (a) {
            lightyear.loading("hide");
            lightyear.notify("文件打包成功，开始下载", "success", 1000);
            window.location.href = "/downloadZipFile?tempFile=" + a.tempFile
        }, error: function (a) {
            console.error(a.message);
            lightyear.loading("hide");
            lightyear.notify("打包文件失败", "danger", 1000)
        }
    })
}

function downloadFiles() {
    if (tabPage === 1) {
        downloadFile()
    } else {
        if (tabPage === 2) {
            downloadMedia()
        }
    }
}

function setActiveNav(page) {
    $(".nav-drawer > li").removeClass("active");
    $("[data-page='" + page + "']").addClass("active");
}

function buildSidebar(menus) {
    var $nav = $("#sidebarNav");
    $nav.empty();
    menus.forEach(function(m) {
        $nav.append(
            '<li class="nav-item nav-item-' + m.key + '" data-page="' + m.key + '">' +
            '<a href="javascript:;" onclick="navTo(\'' + m.key + '\')">' +
            '<i class="' + m.icon + '"></i>' +
            '<span class="nav-text">' + m.text + '</span>' +
            '</a></li>'
        );
    });
}

function locationHashChanged() {
    let url = window.location.hash.substring(1);
    if (url.startsWith("nav-item-apps")) {
        setActiveNav("apps");
        tabPage = 0;
        viewEmpty();
        $(".app-content").show();
        $(".chat-content").hide();
        $(".file-content").hide();
        $(".media-content").hide();
        $(".draw-content").hide();
        appList()
    } else {
        if (url.startsWith("nav-item-files")) {
            setActiveNav("files");
            tabPage = 1;
            viewEmpty();
            $(".app-content").hide();
            $(".chat-content").hide();
            $(".file-content").show();
            $(".media-content").hide();
            $(".draw-content").hide();
            var c = "nav-item-files";
            var qIdx = url.indexOf("?");
            var b = qIdx > c.length ? url.substring(c.length, qIdx) : rootPath;
            var a = qIdx >= 0 ? url.substring(url.lastIndexOf("=") + 1) === "true" : false;
            openDir(a, decodeURIComponent(b))
        } else {
            if (url.startsWith("nav-item-media")) {
                setActiveNav("media");
                tabPage = 2;
                let qIdx2 = url.indexOf("?");
                let index = qIdx2 >= 0 ? (url.substring(qIdx2 + 1).split("=")[1] - 0) : -1;
                viewEmpty();
                $(".chat-content").hide();
                $(".app-content").hide();
                $(".file-content").hide();
                $(".draw-content").hide();
                $(".media-content").show();
                mediaList(index)
            } else {
                if (url.startsWith("nav-item-draw")) {
                    setActiveNav("draw");
                    tabPage = 4;
                    viewEmpty();
                    $(".app-content").hide();
                    $(".file-content").hide();
                    $(".media-content").hide();
                    $(".chat-content").hide();
                    $(".draw-content").show();
                    initDrawCanvas()
                } else {
                    setActiveNav("chat");
                    tabPage = 3;
                    viewEmpty();
                    $(".app-content").hide();
                    $(".file-content").hide();
                    $(".media-content").hide();
                    $(".draw-content").hide();
                    $(".chat-content").show()
                }
            }
        }
    }
};